import numpy as np
from scipy.optimize import linprog, minimize


def construct_packing():
    n = 26
    best_centers = None
    best_sum = -1

    inits = []
    for s in [0.15, 0.16]:
        pts = hex_lattice(s)
        if len(pts) >= 26:
            dists = np.sqrt((pts[:, 0] - 0.5)**2 + (pts[:, 1] - 0.5)**2)
            idx = np.argsort(dists)
            inits.append(pts[idx[:26]].copy())

    grid_pts = []
    for i in range(5):
        for j in range(5):
            grid_pts.append([0.1 + i*0.2, 0.1 + j*0.2])
    grid_pts.append([0.5, 0.5])
    inits.append(np.array(grid_pts[:26]))

    for init in inits:
        result = minimize(
            lambda x: -lp_sum_fast(x.reshape(26, 2)),
            init.flatten(),
            method='L-BFGS-B',
            bounds=[(0.01, 0.99)] * 52,
            options={'maxiter': 60, 'ftol': 1e-6}
        )
        opt_centers = result.x.reshape(26, 2)
        radii = solve_max_radii_lp(opt_centers)
        s_sum = np.sum(radii)
        if s_sum > best_sum:
            best_sum = s_sum
            best_centers = opt_centers.copy()

    # Refinement
    result = minimize(
        lambda x: -lp_sum_fast(x.reshape(26, 2)),
        best_centers.flatten(),
        method='L-BFGS-B',
        bounds=[(0.01, 0.99)] * 52,
        options={'maxiter': 80, 'ftol': 1e-8}
    )
    opt_centers = result.x.reshape(26, 2)
    radii = solve_max_radii_lp(opt_centers)
    s_sum = np.sum(radii)
    if s_sum > best_sum:
        best_sum = s_sum
        best_centers = opt_centers.copy()

    radii = solve_max_radii_lp(best_centers)
    return best_centers, radii, np.sum(radii)


def hex_lattice(s):
    dy = s * np.sqrt(3) / 2
    pts = []
    row = 0
    y = 0.02
    while y <= 0.98:
        x_offset = (s / 2) if (row % 2 == 1) else 0
        x = 0.02 + x_offset
        while x <= 0.98:
            pts.append([x, y])
            x += s
        y += dy
        row += 1
    return np.array(pts)


def lp_sum_fast(centers):
    n = centers.shape[0]
    radii = np.zeros(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y) * 0.8
    dists = np.zeros((n, n))
    for i in range(n):
        for j in range(i+1, n):
            d = np.sqrt(np.sum((centers[i] - centers[j])**2))
            dists[i,j] = d
            dists[j,i] = d
    for _ in range(30):
        for i in range(n):
            max_r = min(centers[i,0], centers[i,1], 1-centers[i,0], 1-centers[i,1])
            for j in range(n):
                if i != j:
                    max_r = min(max_r, dists[i,j] - radii[j])
            radii[i] = max(0, max_r)
    return np.sum(radii)


def solve_max_radii_lp(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A_rows = []
    b_vals = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            row = np.zeros(n)
            row[i] = 1
            row[j] = 1
            A_rows.append(row)
            b_vals.append(d)
    for i in range(n):
        x, y = centers[i]
        b_dist = min(x, y, 1 - x, 1 - y)
        row = np.zeros(n)
        row[i] = 1
        A_rows.append(row)
        b_vals.append(b_dist)
    A = np.array(A_rows)
    b = np.array(b_vals)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if result.success:
        return np.maximum(result.x, 0)
    else:
        return compute_max_radii_fallback(centers)


def compute_max_radii_fallback(centers):
    n = centers.shape[0]
    radii = np.ones(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y)
    for _ in range(200):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                if radii[i] + radii[j] > dist:
                    scale = dist / (radii[i] + radii[j])
                    radii[i] *= scale
                    radii[j] *= scale
    return radii

